#!/usr/bin/env python3
"""Generate basic diagram definitions; no renderer or random seed is required.

The graph model is a breadth-first balanced binary tree. Node i has parent
(i - 1) // 2 for i > 0. All nodes have fixed-width labels and rectangular
shapes; all edges are directed from parent to child and have no labels.
"""
from __future__ import annotations

import argparse
from pathlib import Path


SIZES = (2, 10, 100)


def source(nodes: int) -> str:
    if nodes not in SIZES:
        raise ValueError(f'Unsupported basic diagram size: {nodes}')
    lines = [
        '# Generated by corpus/generators/basic.py; see corpus/PROVENANCE.md.',
        '# Copyright (c) 2026 D2 Authors. SPDX-License-Identifier: MIT',
        '# Balanced binary tree, breadth-first IDs, identical fixed-width labels.',
        'direction: down',
        '',
    ]
    lines.extend(f'n{i:03d}: Node {i:03d} {{shape: rectangle}}' for i in range(nodes))
    lines.append('')
    lines.extend(f'n{(i - 1) // 2:03d} -> n{i:03d}' for i in range(1, nodes))
    return '\n'.join(lines) + '\n'


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, required=True,
                        help='New directory for the three generated D2 inputs')
    args = parser.parse_args()
    if args.output.exists():
        parser.error('Output already exists; choose a new directory')
    args.output.mkdir(parents=True)
    for size in SIZES:
        (args.output / f'basic_{size:03d}.d2').write_text(source(size), encoding='utf-8')


if __name__ == '__main__':
    main()
